#!/usr/bin/env bash
# B2 / TD-14 / H-1..H-3 owner simulation. Phase 6 revision 2 (Agent 3, 5 Nov 2026, after owner
# run 1: ContextKeyType arn is not an API value; boundary documents over the 2000-character
# policyInputList member limit; 4 calls named a resource type the action does not use). Revision 1
# (4 Nov 2026) was itself a revision of the Phase 5
# script docs/aws-migration/agent-reports/2026-11-04-phase5/supporting/b2-owner-simulation.sh
# (Agent 2, 214 simulate calls). This revision: 332 simulate calls.
#
# READ ONLY. The only AWS calls are sts get-caller-identity, kms describe-key (the state key
# alias, to learn the key ARN), iam list-attached-role-policies, iam list-role-policies,
# iam get-policy, iam get-policy-version, iam simulate-principal-policy and
# iam simulate-custom-policy. Nothing is created, changed or deleted. No secret value is read.
#
# When and where: AWS CloudShell, eu-central-1, signed in as root, AFTER the root re-apply of
# infra/aws/bootstrap with platform#38 (main 46dfbd9). Before that re-apply the deployers carry
# the old policies; the preflight below then stops with exit 2 instead of reporting noise.
#
# Usage:   bash b2-owner-simulation.sh [results-file]
# Output:  one PASS or FAIL line per call; a tab-separated results file (default
#          ./b2-owner-simulation-results-<UTC time>.tsv: verdict, id, expected, actual,
#          principal, description); and as the very last line
#          RESULT total=<n> expected_match=<n> unexpected_mismatch=<n> ...
# Exit:    0 only if every call returned its expected decision and all 332 ran;
#          1 on any mismatch or API error; 2 if a precondition failed (nothing simulated).
#
# Every call passes aws:RequestedRegion (eu-central-1 unless the case tests another region),
# which the ThisRegionOnly denies need. The simulator applies the context keys to every resource
# of a call, so a multi-resource request (an EC2 create: the parent and the new resource) is
# simulated once per resource with that resource's own tags (lines .1, .2); the request passes
# only if every line passes. The B and BP cases simulate the boundary documents themselves
# (simulate-custom-policy), as no stack role exists yet.
#
# Expected values: Phase 5 local evaluation, re-checked in Phase 6 by an independent local
# evaluator against policies rendered offline from 46dfbd9. Neither is an AWS simulation; this
# script is. Not covered by the simulator: key policies, bucket policies, SCPs.
set -uo pipefail
export AWS_REGION=eu-central-1 AWS_DEFAULT_REGION=eu-central-1 AWS_PAGER="" AWS_RETRY_MODE=standard AWS_MAX_ATTEMPTS=8
ACCOUNT=229251310592
EXPECTED_TOTAL=332
RESULTS=${1:-"./b2-owner-simulation-results-$(date -u +%Y%m%dT%H%M%SZ).tsv"}
WORK=$(mktemp -d) || exit 2
trap 'rm -rf "$WORK"' EXIT
pass=0; fail=0

precondition_failed() {
  echo "PRECONDITION FAILED: $1"
  echo "RESULT total=0 expected_match=0 unexpected_mismatch=0 expected_total=$EXPECTED_TOTAL preflight=failed results=none"
  exit 2
}

# --- Preflight (read only) ---------------------------------------------------------------------
caller=$(aws sts get-caller-identity --query '[Account,Arn]' --output text 2>&1) || precondition_failed "sts get-caller-identity: $caller"
[ "$(printf '%s' "$caller" | cut -f1)" = "$ACCOUNT" ] || precondition_failed "wrong account: $caller"
echo "caller: $(printf '%s' "$caller" | cut -f2)"

STATE_KEY_ARN=$(aws kms describe-key --key-id alias/munaxa-shared-tfstate --query KeyMetadata.Arn --output text 2>&1) \
  || precondition_failed "kms describe-key alias/munaxa-shared-tfstate: $STATE_KEY_ARN"
case "$STATE_KEY_ARN" in arn:aws:kms:eu-central-1:$ACCOUNT:key/*) ;; *) precondition_failed "unexpected state key ARN: $STATE_KEY_ARN" ;; esac
echo "state key: $STATE_KEY_ARN"

expect_attached() { # role-name policy-name...
  local role=$1 got; shift
  got=$(aws iam list-attached-role-policies --role-name "$role" --query 'AttachedPolicies[].PolicyName' --output text 2>&1) \
    || precondition_failed "list-attached-role-policies $role: $got"
  for p in "$@"; do
    printf '%s\n' $got | grep -qx "$p" || precondition_failed "$role lacks managed policy $p (is the #38 re-apply done?)"
  done
}
expect_inline() { # role-name policy-name
  local got
  got=$(aws iam list-role-policies --role-name "$1" --query 'PolicyNames' --output text 2>&1) || precondition_failed "list-role-policies $1: $got"
  printf '%s\n' $got | grep -qx "$2" || precondition_failed "$1 lacks inline policy $2"
}
expect_attached munaxa-shared-deployer-nonprod munaxa-shared-deployer-read munaxa-shared-deployer-nonprod-allow munaxa-shared-deployer-nonprod-allow-tagged
expect_attached munaxa-shared-deployer-prod munaxa-shared-deployer-read munaxa-shared-deployer-prod-allow munaxa-shared-deployer-prod-allow-tagged
expect_attached munaxa-shared-deployer-nonprod-session munaxa-shared-deployer-read munaxa-shared-deployer-nonprod-session-read
expect_inline munaxa-shared-deployer-nonprod deployer
expect_inline munaxa-shared-deployer-prod deployer
expect_inline munaxa-shared-deployer-nonprod-session session-deployer
expect_inline munaxa-shared-ci-nonprod-session assume-own-session-deployer-only

fetch_policy() { # policy-arn out-file
  local v
  v=$(aws iam get-policy --policy-arn "$1" --query Policy.DefaultVersionId --output text 2>&1) || precondition_failed "get-policy $1: $v"
  aws iam get-policy-version --policy-arn "$1" --version-id "$v" --query PolicyVersion.Document --output json > "$2" 2>"$WORK/err" \
    || precondition_failed "get-policy-version $1: $(cat "$WORK/err")"
}
BOUNDARY_NONPROD_ARN=arn:aws:iam::$ACCOUNT:policy/munaxa-shared/munaxa-shared-workload-boundary
BOUNDARY_PROD_ARN=arn:aws:iam::$ACCOUNT:policy/munaxa-shared/munaxa-shared-workload-boundary-prod
fetch_policy "$BOUNDARY_NONPROD_ARN" "$WORK/boundary-nonprod.json"
fetch_policy "$BOUNDARY_PROD_ARN" "$WORK/boundary-prod.json"
# SimulateCustomPolicy refused each boundary as one document (run 1, 5 Nov 2026: "Value at
# 'policyInputList' failed to satisfy constraint: Member must have length less than or equal to
# 2000"; the boundaries are 2,635 and 2,611 characters minified). The boundary is therefore passed
# as several minified documents of at most 1,500 characters (a margin below 2,000), each holding
# whole statements. IAM
# evaluates several identity policies as one set (any explicit deny wins, else any allow), so the
# decision is the same as for the single document. The split is checked: same statements, same order.
command -v python3 >/dev/null || precondition_failed "python3 not found (CloudShell has it)"
split_policy() { # in-file out-file (a JSON array of policy strings, each <= 1500 characters)
  python3 -I - "$1" "$2" <<'PY' || precondition_failed "cannot split $1 into documents of at most 1500 characters"
import json, sys
doc = json.load(open(sys.argv[1]))
st = doc["Statement"] if isinstance(doc["Statement"], list) else [doc["Statement"]]
def text(s): return json.dumps({"Version": doc.get("Version", "2012-10-17"), "Statement": s}, separators=(",", ":"))
parts, cur = [], []
for s in st:
    if cur and len(text(cur + [s])) > 1500:  # margin below the 2000 limit
        parts.append(cur); cur = []
    cur.append(s)
if cur: parts.append(cur)
docs = [text(p) for p in parts]
assert all(len(d) <= 1500 for d in docs), [len(d) for d in docs]
assert [s for d in docs for s in json.loads(d)["Statement"]] == st
json.dump(docs, open(sys.argv[2], "w"))
print("%s: %d statements in %d documents of %s characters" % (sys.argv[1].rsplit("/", 1)[-1], len(st), len(docs), "/".join(str(len(d)) for d in docs)))
PY
}
for f in boundary-nonprod boundary-prod; do # OwnRdsMasterSecretByTag exists only in the #38 (0ff0879) boundaries
  grep -q '"OwnRdsMasterSecretByTag"' "$WORK/$f.json" || precondition_failed "$f is not the #38 version (no OwnRdsMasterSecretByTag)"
  split_policy "$WORK/$f.json" "$WORK/$f.list.json"
done

printf 'verdict\tid\texpected\tactual\tprincipal\tdescription\n' > "$RESULTS" || precondition_failed "cannot write $RESULTS"

# --- Simulation helpers ------------------------------------------------------------------------
decision() { # rc output principal -> "decision|principal" (an API error becomes ERROR...)
  local rc=$1 out=$2 who=$3
  out=${out//$'\n'/ }; out=${out//$'\t'/ }; out=${out//|//}
  case "$rc:$out" in
    0:allowed | 0:explicitDeny | 0:implicitDeny) printf '%s|%s\n' "$out" "$who" ;;
    *) printf 'ERROR(rc=%s):%.300s|%s\n' "$rc" "$out" "$who" ;;
  esac
}
sim() { # role-arn action resource context-json
  local out rc
  out=$(aws iam simulate-principal-policy --policy-source-arn "$1" --action-names "$2" --resource-arns "$3" \
    --context-entries "$4" --query 'EvaluationResults[0].EvalDecision' --output text 2>&1); rc=$?
  decision "$rc" "$out" "${1##*/}"
}
simdoc() { # policy-list-file (JSON array of policy strings) label action resource context-json
  local out rc
  out=$(aws iam simulate-custom-policy --policy-input-list "file://$1" --action-names "$3" --resource-arns "$4" \
    --context-entries "$5" --query 'EvaluationResults[0].EvalDecision' --output text 2>&1); rc=$?
  decision "$rc" "$out" "$2"
}
simb() { simdoc "$WORK/boundary-nonprod.list.json" boundary-nonprod "$@"; }
simbp() { simdoc "$WORK/boundary-prod.list.json" boundary-prod "$@"; }
check() { # id expected "decision|principal" description
  local id=$1 exp=$2 act=${3%|*} who=${3##*|} desc=$4 verdict
  if [ "$exp" = "$act" ]; then pass=$((pass + 1)); verdict=PASS; echo "PASS $id $act  $desc"
  else fail=$((fail + 1)); verdict=FAIL; echo "FAIL $id expected=$exp actual=$act  $desc"; fi
  printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$verdict" "$id" "$exp" "$act" "$who" "$desc" >> "$RESULTS"
}

